def copy_manual_conference(apps, schema_editor):
    """A conferência manual era da conta inteira: cada filial herda o que a conta tinha."""
    StockSettings = apps.get_model("starrp", "StockSettings")
    Store = apps.get_model("starrp", "Store")
    LogisticsSettings = apps.get_model("starrp", "LogisticsSettings")
    for policy in StockSettings._default_manager.filter(deleted_at__isnull=True, allow_manual_conference=True):
        for store in Store._default_manager.filter(account_id=policy.account_id, deleted_at__isnull=True):
            LogisticsSettings._default_manager.update_or_create(
                store=store, deleted_at=None, defaults={"account_id": store.account_id, "allow_manual_conference": True})


